theme.css:
/* theme: Whiplash Rally | Green screens and red ink, an impulsive day of tech surges, crude plunges, and politicking — designed with electric market pulse. */
.diary-page {
  --paper: #f4f1e8;
  --paper-alt: #e8e2d2;
  --ink: #1a1a1a;
  --ink-soft: #3a3a3a;
  --muted: #4d4d42;
  --accent: #1b5e20;
  --accent-ink: #ffffff;
  --rule: #c9c2b0;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

.diary-page { background: var(--paper); color: var(--ink-soft); }
.diary-page .diary-hero { background: var(--paper-alt); border-bottom: 3px solid var(--accent); }
.diary-page .diary-hero-inner { padding-block: 2.5rem 3.5rem; }
.diary-page .diary-crumbs a { font-family: var(--font-ui); font-size: 0.8rem; letter-spacing: 1px; text-transform: uppercase; color: var(--muted); }
.diary-page .diary-crumbs a::before { content: "↩"; margin-right: 0.5rem; }
.diary-page .diary-kicker { font-family: var(--font-ui); font-weight: 700; letter-spacing: 0.2em; font-size: 0.75rem; margin-top: 2rem; color: var(--accent); }
.diary-page .diary-title { font-family: var(--font-display); font-size: clamp(2.8rem, 8vw, 6rem); letter-spacing: 0.04em; line-height: 0.95; max-width: 18ch; margin-top: 0.8rem; color: var(--ink); }
.diary-page .diary-summary { font-family: var(--font-body); font-size: clamp(1.2rem, 2vw, 1.5rem); line-height: 1.6; max-width: 50rem; margin-top: 1.8rem; color: var(--ink-soft); }
.diary-page .diary-theme-note { font-family: var(--font-ui); font-size: 0.85rem; letter-spacing: 0.5px; margin-top: 1.8rem; color: var(--muted); }
.diary-page .diary-theme-name { background: var(--accent); color: var(--accent-ink); font-weight: 700; padding: 0.2rem 0.7rem; border-radius: 2px; margin-right: 0.6rem; text-transform: uppercase; font-size: 0.7rem; letter-spacing: 0.1em; }
.diary-page .diary-body { grid-template-columns: minmax(0, 1fr); padding-bottom: 4rem; }
@media (min-width: 1024px) {
  .diary-page .diary-body { grid-template-columns: 14rem minmax(0, 1fr); gap: 4rem; padding-top: 2rem; }
}
.diary-page .diary-toc { background: var(--paper); border-bottom: 2px solid var(--rule); margin-inline: -1.25rem; padding: 0.5rem 1.25rem; }
.diary-page .diary-toc-nav { width: max-content; }
.diary-page .diary-toc-list { display: flex; gap: 1.8rem; }
.diary-page .diary-toc-link { font-family: var(--font-ui); font-size: 0.85rem; letter-spacing: 0.5px; font-weight: 500; color: var(--muted); transition: color 150ms; }
.diary-page .diary-toc-link.is-active, .diary-page .diary-toc-link:hover { color: var(--accent); }
.diary-page .diary-toc-number { font-family: var(--font-ui); font-size: 0.75rem; font-weight: 700; color: var(--accent); margin-right: 0.3rem; }
.diary-page .diary-toc-top { font-family: var(--font-ui); font-size: 0.8rem; color: var(--muted); }
@media (min-width: 1024px) {
  .diary-page .diary-toc { top: 2rem; margin: 0; padding: 0; background: none; border: 0; }
  .diary-page .diary-toc-nav { display: block; width: auto; }
  .diary-page .diary-toc-list { flex-direction: column; border-left: 2px solid var(--rule); gap: 0; }
  .diary-page .diary-toc-link { display: flex; margin-left: -2px; padding: 0.6rem 0 0.6rem 1rem; border-left: 3px solid transparent; white-space: normal; }
  .diary-page .diary-toc-link.is-active { border-left-color: var(--accent); color: var(--accent); }
  .diary-page .diary-toc-top { margin-top: 1.5rem; display: inline-block; }
  .diary-page .diary-toc-label { display: block; margin-bottom: 1rem; font-family: var(--font-ui); font-size: 0.7rem; font-weight: 600; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted); }
}
.diary-page .diary-article { max-width: 48rem; }
.diary-page .diary-section { padding-block: 2.5rem; border-top: 1px solid var(--rule); position: relative; }
.diary-page .diary-section:first-child { border-top: 0; }
.diary-page .diary-section-head { margin-bottom: 2rem; }
.diary-page .diary-section-number { font-family: var(--font-ui); font-size: 0.8rem; font-weight: 700; letter-spacing: 0.15em; color: var(--accent); }
.diary-page .diary-section-title { font-family: var(--font-display); font-size: clamp(2rem, 4vw, 3.5rem); letter-spacing: 0.03em; color: var(--ink); font-weight: 400; margin-top: 0.2rem; }
.diary-page .diary-prose { font-size: 1.15rem; line-height: 1.8; color: var(--ink-soft); }
.diary-page .diary-prose h3 { font-family: var(--font-ui); font-size: 0.8rem; font-weight: 700; letter-spacing: 0.18em; text-transform: uppercase; color: var(--accent); border-bottom: 2px solid var(--accent); display: inline-block; padding-bottom: 0.3rem; margin-top: 2.5em; }
.diary-page .diary-prose h4 { font-family: var(--font-body); font-size: 1.35rem; font-weight: 600; letter-spacing: 0.01em; margin-top: 1.8em; color: var(--ink); }
.diary-page .diary-prose strong { font-weight: 600; color: var(--ink); }
.diary-page .diary-prose ul > li::before { background: var(--accent); width: 0.7rem; height: 3px; top: 0.8em; }
.diary-page .diary-prose ol > li::marker { color: var(--accent); font-family: var(--font-ui); font-size: 0.9em; font-weight: 700; }
.diary-page .diary-prose blockquote { border-left: 4px solid var(--accent); padding-left: 1.4rem; font-style: italic; color: var(--ink); }
.diary-page .diary-prose pre, .diary-page .diary-prose code { font-family: var(--ff-plex-mono), ui-monospace, monospace; font-size: 0.85rem; }
.diary-page .diary-prose pre { background: var(--paper-alt); border: 1px solid var(--rule); border-left: 4px solid var(--accent); }
.diary-page .diary-prose hr { border-top: 2px solid var(--rule); }
.diary-page .diary-section:first-child .diary-prose > p:first-of-type::first-letter { font-family: var(--font-display); font-size: 4.2em; font-weight: 400; color: var(--accent); line-height: 0.8; letter-spacing: 0.02em; }
.diary-page .diary-footer { border-top: 3px solid var(--accent); font-family: var(--font-ui); color: var(--muted); }
.diary-page .diary-footer a { color: var(--accent); font-weight: 600; transition: color 150ms; }
.diary-page .diary-footer a:hover { color: var(--ink); }
.diary-page [data-section="outlook"] { background: var(--paper-alt); border-left: 4px solid var(--accent); padding-left: 1.5rem; padding-right: 1.5rem; }
.diary-page [data-section="outlook"] .diary-section-head, .diary-page [data-section="outlook"] .diary-prose { max-width: 44rem; }
.diary-page [data-section="outlook"] .diary-prose h3 { color: var(--ink); border-bottom-color: var(--ink); }
.diary-page [data-section="music-releases"] .diary-prose ul > li::before { background: var(--accent); }
